mapper.sql:
where p.del_flag = '0'
and p.id = #{id}

    and p.project_code like concat('%', #{projectCode}, '%')


    and p.project_name like concat('%', #{projectName}, '%')

and p.project_type = #{projectType}
and p.project_stage = #{projectStage}
and p.project_status = #{projectStatus}
and p.project_manager_id = #{projectManagerId}

    and date_format(p.create_time, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')


    and date_format(p.create_time, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')

${params.dataScope}

mapper.update:
update cost_project
set project_status = #{projectStatus}, update_by = #{updateBy}, update_time = #{updateTime}
where id = #{id} and del_flag = '0'
